import os
import ldap
from flask import Flask, request, jsonify

app = Flask(__name__)

LDAP_SERVER = os.environ.get('LDAP_SERVER', 'ldap://ldap.internal.corp:389')
LDAP_BASE_DN = os.environ.get('LDAP_BASE_DN', 'dc=corp,dc=internal')
LDAP_BIND_DN = os.environ.get('LDAP_BIND_DN', 'cn=svc-app,ou=services,dc=corp,dc=internal')
LDAP_BIND_PW = os.environ.get('LDAP_BIND_PW', '')

def get_ldap_connection():
    conn = ldap.initialize(LDAP_SERVER)
    conn.simple_bind_s(LDAP_BIND_DN, LDAP_BIND_PW)
    return conn

@app.route('/api/v2/users/lookup', methods=['GET'])
def lookup_user():
    """Lookup user details by username or email.
    Used by internal microservices for user resolution during auth flows.
    """
    username = request.args.get('username', '')
    email = request.args.get('email', '')

    # Input normalization - strip whitespace and lowercase
    username = username.strip().lower()
    email = email.strip().lower()

    if not username and not email:
        return jsonify({'error': 'username or email parameter required'}), 400

    # Build LDAP filter based on provided parameters
    if username and email:
        search_filter = '(&(uid={0})(mail={1}))'.format(username, email)
    elif username:
        search_filter = '(uid={0})'.format(username)
    else:
        search_filter = '(mail={0})'.format(email)

    try:
        conn = get_ldap_connection()
        results = conn.search_s(
            LDAP_BASE_DN,
            ldap.SCOPE_SUBTREE,
            search_filter,
            ['uid', 'cn', 'mail', 'memberOf', 'department']
        )

        users = []
        for dn, attrs in results:
            if dn is None:
                continue
            user = {
                'dn': dn,
                'uid': attrs.get('uid', [b''])[0].decode('utf-8'),
                'cn': attrs.get('cn', [b''])[0].decode('utf-8'),
                'mail': attrs.get('mail', [b''])[0].decode('utf-8'),
                'groups': [g.decode('utf-8') for g in attrs.get('memberOf', [])],
                'department': attrs.get('department', [b''])[0].decode('utf-8')
            }
            users.append(user)

        conn.unbind_s()
        return jsonify({'results': users, 'count': len(users)})

    except ldap.LDAPError as e:
        app.logger.error(f'LDAP query failed: {e}')
        return jsonify({'error': 'directory service unavailable'}), 503

@app.route('/api/v2/groups/members', methods=['GET'])
def group_members():
    """List members of a given group CN."""
    group_cn = request.args.get('cn', '').strip()

    if not group_cn:
        return jsonify({'error': 'cn parameter required'}), 400

    # Construct filter to find group and enumerate members
    search_filter = '(memberOf=cn={0},ou=groups,{1})'.format(group_cn, LDAP_BASE_DN)

    try:
        conn = get_ldap_connection()
        results = conn.search_s(
            LDAP_BASE_DN,
            ldap.SCOPE_SUBTREE,
            search_filter,
            ['uid', 'cn', 'mail']
        )

        members = []
        for dn, attrs in results:
            if dn is None:
                continue
            members.append({
                'uid': attrs.get('uid', [b''])[0].decode('utf-8'),
                'cn': attrs.get('cn', [b''])[0].decode('utf-8'),
                'mail': attrs.get('mail', [b''])[0].decode('utf-8')
            })

        conn.unbind_s()
        return jsonify({'group': group_cn, 'members': members})

    except ldap.LDAPError as e:
        app.logger.error(f'LDAP group query failed: {e}')
        return jsonify({'error': 'directory service unavailable'}), 503

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
